// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    Recorder rec;

    function setUp() public { c = new airPort(); rec = new Recorder(); }

    // fuzz the from address and a single recipient encoded in an array of length 1 and a value
    function testFuzz_property(address from, uint256 v) public {
        // keep recipient as recorder's address (adversarial/observing counterparty)
        address to = address(rec);
        address caddr = address(rec);

        // require nonzero array length is enforced by C; ensure fuzzed `from` is a non-zero address to be meaningful
        vm.assume(from != address(0));

        // build single-element array on the stack
        address[] memory tos = new address[](1);
        tos[0] = to;

        // call C.transfer and ignore revert propagation by capturing success
        bool ok;
        try c.transfer(from, caddr, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation ALWAYS calls the callee with selector keccak256("transferFrom(address,address,uint256)")
        // Recorder exposes lastSelector and callCount. We assert that if C completed (ok==true) then recorder saw at least one call
        // and that the recorded selector equals the transferFrom selector. This holds for the reference and is violated by the mutant.

        bytes4 expected = bytes4(keccak256("transferFrom(address,address,uint256)"));

        // Only assert when C did not revert, since both variants may revert on some inputs.
        if (ok) {
            // require at least one call was observed
            assertTrue(rec.callCount() >= 1);
            // the recorded selector must equal the expected transferFrom selector for the reference; mutant will record different selector
            assertTrue(rec.lastSelector() == expected);
        } else {
            // if C reverted, still consistent: do not assert selector (revert behavior may be same or different)
            assertTrue(true);
        }
    }
}

// Recorder that declares the transferFrom and transfer signatures and records calldata selector and a counter
contract Recorder {
    uint256 private _count;
    bytes4 private _lastSelector;
    address private _lastFrom;
    address private _lastTo;
    uint256 private _lastV;

    // function matching transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        _count += 1;
        _lastSelector = bytes4(msg.sig);
        _lastFrom = from;
        _lastTo = to;
        _lastV = v;
        return true;
    }

    // function matching transfer(address,address,uint256) in mutant; record if called
    function transfer(address from, address to, uint256 v) external returns (bool) {
        _count += 1;
        _lastSelector = bytes4(msg.sig);
        _lastFrom = from;
        _lastTo = to;
        _lastV = v;
        return true;
    }

    // getters for the test to observe
    function callCount() external view returns (uint256) { return _count; }
    function lastSelector() external view returns (bytes4) { return _lastSelector; }
    function lastFrom() external view returns (address) { return _lastFrom; }
    function lastTo() external view returns (address) { return _lastTo; }
    function lastV() external view returns (uint256) { return _lastV; }
}
